import React, { useEffect, useMemo, useRef, useState } from "react";
import { AccessibilityInfo, PanResponder, View, type ViewStyle } from "react-native";
import { Canvas, Fill, Shader, Skia } from "@shopify/react-native-skia";
import { useDerivedValue, useFrameCallback, useSharedValue } from "react-native-reanimated";
import {
  FERRO_DEFAULTS,
  createFerro,
  ferroDown,
  ferroMove,
  ferroRelease,
  ferroStep,
  type FerroState,
} from "./ferroMath";
import { FERRO_BACKGROUND, FERRO_H, FERRO_W } from "./ferroDesign";
import { FERRO_SHADER } from "./ferroShader";

export type FerrofluidProps = {
  slowMotion?: boolean;
  reducedMotion?: boolean;
  onFeedback?: (event: "touch" | "release") => void;
  label?: string;
  style?: ViewStyle;
};

type Pointer = { x: number; y: number; down: number; seq: number };

const SKSL = `${FERRO_SHADER}
half4 main(float2 p) {
  return half4(half3(ferrofluidColor(p)), 1.0);
}
`;

let cachedEffect: ReturnType<typeof Skia.RuntimeEffect.Make> | undefined;
function getEffect() {
  if (cachedEffect === undefined) cachedEffect = Skia.RuntimeEffect.Make(SKSL);
  return cachedEffect;
}

// Android stops presenting a canvas whose only change is a shader uniform on an
// idle screen. A 1 px layout change every frame keeps it drawing.
function CanvasKeepAlive() {
  const [beat, setBeat] = useState(0);
  useEffect(() => {
    let cancelled = false;
    const tick = () => {
      if (cancelled) return;
      setBeat((b) => b + 1);
      requestAnimationFrame(tick);
    };
    const id = requestAnimationFrame(tick);
    return () => {
      cancelled = true;
      cancelAnimationFrame(id);
    };
  }, []);
  return (
    <View
      pointerEvents="none"
      style={{ position: "absolute", width: 1, height: 1, opacity: 0, transform: [{ translateX: beat % 2 }] }}
    />
  );
}

export function Ferrofluid({
  slowMotion = false,
  reducedMotion,
  onFeedback,
  label = "Black ferrofluid that grows spikes toward your finger",
  style,
}: FerrofluidProps) {
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const opts = useMemo(() => FERRO_DEFAULTS, []);
  const effect = useMemo(() => getEffect(), []);
  const st = useSharedValue<FerroState>(createFerro(FERRO_W / 2, FERRO_H * 0.5));
  const frame = useSharedValue(0);
  const pointer = useSharedValue<Pointer>({ x: 0, y: 0, down: 0, seq: 0 });
  const slowM = useSharedValue(false);
  const reduceM = useSharedValue(false);
  const latest = useRef({ reduce, onFeedback, seq: 0 });
  latest.current.reduce = reduce;
  latest.current.onFeedback = onFeedback;

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => {
        if (alive) setSystemReduce(v);
      })
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);
  useEffect(() => {
    slowM.value = slowMotion;
  }, [slowMotion, slowM]);
  useEffect(() => {
    reduceM.value = reduce;
    const fresh = createFerro(FERRO_W / 2, FERRO_H * 0.5);
    if (reduce) fresh.s = 1; // still picture: spikes standing under the middle
    st.value = fresh;
    frame.value = frame.value + 1;
  }, [reduce, reduceM, st, frame]);

  const pan = useMemo(() => {
    const send = (x: number, y: number, down: number) => {
      latest.current.seq += 1;
      pointer.value = { x, y, down, seq: latest.current.seq };
    };
    return PanResponder.create({
      onStartShouldSetPanResponder: () => !latest.current.reduce,
      onPanResponderGrant: (evt) => {
        send(evt.nativeEvent.locationX, evt.nativeEvent.locationY, 1);
        latest.current.onFeedback?.("touch");
      },
      onPanResponderMove: (evt) => {
        send(evt.nativeEvent.locationX, evt.nativeEvent.locationY, 1);
      },
      onPanResponderRelease: () => {
        send(pointer.value.x, pointer.value.y, 0);
        latest.current.onFeedback?.("release");
      },
      onPanResponderTerminate: () => {
        send(pointer.value.x, pointer.value.y, 0);
      },
      onPanResponderTerminationRequest: () => false,
    });
  }, [pointer]);

  useFrameCallback((info) => {
    if (reduceM.value) return;
    const s = st.value;
    const p = pointer.value;
    if (p.seq !== s.seq) {
      if (p.down && !s.down) ferroDown(s, p.x, p.y);
      else if (p.down) ferroMove(s, p.x, p.y);
      else ferroRelease(s);
      s.seq = p.seq;
    }
    const dt = Math.min(48, info.timeSincePreviousFrame ?? 16.7) / 1000;
    ferroStep(s, dt * (slowM.value ? 0.25 : 1), opts);
    frame.value = frame.value + 1;
  });

  const uniforms = useDerivedValue(() => {
    frame.value;
    const s = st.value;
    return { size: [FERRO_W, FERRO_H], mag: [s.mx, s.my, s.s, 0] };
  });

  return (
    <View
      style={[{ width: FERRO_W, height: FERRO_H, borderRadius: 18, overflow: "hidden", backgroundColor: FERRO_BACKGROUND }, style]}
      accessibilityLabel={label}
      accessibilityRole="image"
      {...pan.panHandlers}
    >
      {!reduce ? <CanvasKeepAlive /> : null}
      <Canvas pointerEvents="none" style={{ width: FERRO_W, height: FERRO_H }}>
        <Fill color={FERRO_BACKGROUND} />
        {effect ? (
          <Fill>
            <Shader source={effect} uniforms={uniforms} />
          </Fill>
        ) : null}
      </Canvas>
    </View>
  );
}

// The dish is 130 mm wide and drawn 320 px wide (FERRO_W and FERRO_DISH_MM in ferroDesign.ts).
export const FERRO_PX_PER_MM = 320 / 130;

// Ferrofluid physics for the Rosensweig (normal-field) instability.
// Units: SI unless a name ends in Px or Mm.

export const MU0 = 4e-7 * Math.PI;
export const FERRO_DEFAULTS = {
  surfaceTension: 0.028, // N/m, typical oil-based ferrofluid
  density: 1190, // kg/m^3
  gravity: 9.81,
  relativePermeability: 2.0, // linear-response permeability at onset
  magnetDepthMm: 40, // magnet centre below the fluid surface
  peakRatio: 2.8, // M/Mc straight above the magnet at full strength
  maxHeightPx: 42, // saturated spike height
  baseRadiusFactor: 0.47, // spike base radius as a fraction of spacing
  strengthOmega: 13, // field ramp spring, rad/s
  strengthDamping: 0.45, // under-damped, so the spikes overshoot a little
  followOmega: 15, // magnet follows the finger with this spring
  followDamping: 0.9,
  fixedDt: 1 / 240,
};
export type FerroOptions = typeof FERRO_DEFAULTS;

// Capillary length: the scale where gravity and surface tension balance.
export function capillaryLength(o: FerroOptions = FERRO_DEFAULTS) {
  "worklet";
  return Math.sqrt(o.surfaceTension / (o.density * o.gravity));
}
// Critical wavelength of the instability: 2 pi times the capillary length.
export function criticalWavelength(o: FerroOptions = FERRO_DEFAULTS) {
  "worklet";
  return 2 * Math.PI * capillaryLength(o);
}
// Spikes sit on a hexagonal lattice. For a hexagonal pattern with wavenumber k
// the nearest-neighbour distance is 4 pi / (sqrt(3) k) = 2 lambda / sqrt(3).
export function latticeSpacingMm(o: FerroOptions = FERRO_DEFAULTS) {
  "worklet";
  return ((2 * criticalWavelength(o)) / Math.sqrt(3)) * 1000;
}
export function latticeSpacingPx(o: FerroOptions = FERRO_DEFAULTS) {
  "worklet";
  return latticeSpacingMm(o) * FERRO_PX_PER_MM;
}
// Cowley-Rosensweig onset: mu0 Mc^2 = 2 (1 + 1/mu_r) sqrt(rho g sigma).
export function criticalMagnetization(o: FerroOptions = FERRO_DEFAULTS) {
  "worklet";
  const p = Math.sqrt(o.density * o.gravity * o.surfaceTension);
  return Math.sqrt((2 * (1 + 1 / o.relativePermeability) * p) / MU0);
}

// |B| of a point dipole pointing up, at lateral distance r from the axis and
// depth d below the surface point: sqrt(4 d^4 + 5 d^2 r^2 + r^4) / R^5 with
// R^2 = r^2 + d^2 (times mu0 m / 4 pi). Normalised so r = 0 gives 1.
export function dipoleShape(r: number, d: number) {
  "worklet";
  const z2 = d * d;
  const r2 = r * r;
  const R2 = r2 + z2;
  return (0.5 * d * d * d * Math.sqrt(4 * z2 * z2 + 5 * z2 * r2 + r2 * r2)) / (R2 * R2 * Math.sqrt(R2));
}
// M / Mc at lateral distance rPx from the magnet at full strength.
export function fieldRatio(rPx: number, o: FerroOptions = FERRO_DEFAULTS) {
  "worklet";
  return o.peakRatio * dipoleShape(rPx, o.magnetDepthMm * FERRO_PX_PER_MM);
}
// Spike height for field ratio m = M/Mc. Zero below onset; grows like the
// square root of the distance above onset (supercritical pitchfork), then
// saturates.
export function spikeHeight(m: number, o: FerroOptions = FERRO_DEFAULTS) {
  "worklet";
  const eps = m * m - 1;
  if (eps <= 0) return 0;
  return o.maxHeightPx * (1 - 2 / (Math.exp(1.6 * Math.sqrt(eps)) + 1));
}
// Radius (px) inside which spikes stand at full magnet strength.
export function spikeRadiusPx(o: FerroOptions = FERRO_DEFAULTS) {
  "worklet";
  let lo = 0;
  let hi = 600;
  for (let i = 0; i < 40; i++) {
    const mid = (lo + hi) / 2;
    if (fieldRatio(mid, o) > 1) lo = mid;
    else hi = mid;
  }
  return lo;
}

export type FerroState = {
  mx: number;
  my: number;
  mvx: number;
  mvy: number;
  tx: number;
  ty: number;
  s: number;
  sv: number;
  down: number;
  seq: number;
};

export function createFerro(x: number, y: number): FerroState {
  "worklet";
  return { mx: x, my: y, mvx: 0, mvy: 0, tx: x, ty: y, s: 0, sv: 0, down: 0, seq: 0 };
}
export function ferroDown(st: FerroState, x: number, y: number) {
  "worklet";
  st.down = 1;
  st.tx = x;
  st.ty = y;
  if (st.s < 0.05) {
    st.mx = x;
    st.my = y;
    st.mvx = 0;
    st.mvy = 0;
  }
}
export function ferroMove(st: FerroState, x: number, y: number) {
  "worklet";
  st.tx = x;
  st.ty = y;
}
export function ferroRelease(st: FerroState) {
  "worklet";
  st.down = 0;
}
// Advance the magnet and the field strength. Returns true while anything moves.
export function ferroStep(st: FerroState, dt: number, o: FerroOptions = FERRO_DEFAULTS) {
  "worklet";
  const n = Math.max(1, Math.ceil(dt / o.fixedDt));
  const h = dt / n;
  const target = st.down ? 1 : 0;
  const ws = o.strengthOmega;
  const wf = o.followOmega;
  for (let i = 0; i < n; i++) {
    st.sv += (ws * ws * (target - st.s) - 2 * o.strengthDamping * ws * st.sv) * h;
    st.s += st.sv * h;
    if (st.s < 0) {
      st.s = 0;
      if (st.sv < 0) st.sv = 0;
    }
    st.mvx += (wf * wf * (st.tx - st.mx) - 2 * o.followDamping * wf * st.mvx) * h;
    st.mvy += (wf * wf * (st.ty - st.my) - 2 * o.followDamping * wf * st.mvy) * h;
    st.mx += st.mvx * h;
    st.my += st.mvy * h;
  }
  return (
    st.down === 1 ||
    Math.abs(st.s) > 1e-3 ||
    Math.abs(st.sv) > 1e-3 ||
    Math.abs(st.tx - st.mx) > 0.05 ||
    Math.abs(st.ty - st.my) > 0.05
  );
}

import { FERRO_DEFAULTS, FERRO_PX_PER_MM, latticeSpacingPx } from "./ferroMath";

const O = FERRO_DEFAULTS;
const f = (n: number) => n.toFixed(5);

// One shader draws the whole thing. The spike lattice, the dipole field and the
// spike heights are the same formulas as ferroMath.ts. The surface is ray
// marched from a camera tilted toward the bottom of the screen, and shaded as
// black glossy metal reflecting a small studio.
export const FERRO_SHADER = `
uniform float2 size;
uniform float4 mag;

const float A = ${f(latticeSpacingPx())};
const float RB = ${f(O.baseRadiusFactor * latticeSpacingPx())};
const float HMAX = ${f(O.maxHeightPx)};
const float DEPTH = ${f(O.magnetDepthMm * FERRO_PX_PER_MM)};
const float PEAK = ${f(O.peakRatio)};
const float ROW = ${f(Math.sqrt(3) / 2)};

float hash21(float2 p) {
  return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}

float fieldRatio(float2 c) {
  float2 d = c - mag.xy;
  float r2 = dot(d, d);
  float z2 = DEPTH * DEPTH;
  float R2 = r2 + z2;
  float b = sqrt(4.0 * z2 * z2 + 5.0 * z2 * r2 + r2 * r2) / (R2 * R2 * sqrt(R2));
  return PEAK * b * DEPTH * DEPTH * DEPTH * 0.5;
}

float spikeAt(float2 c, float jitter) {
  float m = mag.z * fieldRatio(c);
  float eps = m * m - 1.0;
  if (eps <= 0.0) return 0.0;
  return jitter * HMAX * (1.0 - 2.0 / (exp(1.6 * sqrt(eps)) + 1.0));
}

float heightAt(float2 q) {
  float2 o = size * 0.5;
  float2 u = q - o;
  float j = u.y / (A * ROW);
  float i = (u.x - j * A * 0.5) / A;
  float i0 = floor(i);
  float j0 = floor(j);
  float z = 0.0;
  for (int k = 0; k < 4; k++) {
    float di = float(k - (k / 2) * 2);
    float dj = float(k / 2);
    float ci = i0 + di;
    float cj = j0 + dj;
    float2 c = o + float2(ci * A + cj * A * 0.5, cj * A * ROW);
    float jit = 0.95 + 0.1 * hash21(float2(ci, cj));
    float h = spikeAt(c, jit);
    if (h > 0.0) {
      float2 toMag = mag.xy - c;
      float lm = length(toMag);
      float2 lean = toMag / max(lm, 1.0) * (0.22 * min(lm / 70.0, 1.0));
      float u0 = max(1.0 - length(q - c) / RB, 0.0);
      float2 dq = q - c - lean * h * u0 * u0;
      float uu = max(1.0 - length(dq) / RB, 0.0);
      z = max(z, h * uu * uu);
    }
  }
  return z;
}

float3 studio(float3 r) {
  float3 L1 = normalize(float3(-0.28, -0.55, 0.78));
  float3 L2 = normalize(float3(0.85, 0.15, 0.5));
  float3 L3 = normalize(float3(-0.7, 0.5, 0.45));
  float d1 = max(dot(r, L1), 0.0);
  float d2 = max(dot(r, L2), 0.0);
  float d3 = max(dot(r, L3), 0.0);
  float3 col = float3(0.05, 0.06, 0.08);
  col += float3(0.22, 0.26, 0.32) * pow(1.0 - clamp(r.z, 0.0, 1.0), 1.6);
  float band = exp(-pow((r.z - 0.30) / 0.14, 2.0));
  col += float3(0.5, 0.58, 0.72) * band * (0.35 + 0.35 * r.x + 0.2 * r.y);
  col += float3(1.0, 0.98, 0.94) * (0.7 * pow(d1, 24.0) + 3.5 * pow(d1, 220.0));
  float strip1 = pow(max(1.0 - abs(r.x + 0.38) * 5.5, 0.0), 2.0) * smoothstep(0.1, 0.35, r.z);
  float strip2 = pow(max(1.0 - abs(r.x - 0.52) * 7.0, 0.0), 2.0) * smoothstep(0.1, 0.35, r.z);
  col += float3(1.0, 0.97, 0.92) * strip1 * 1.5 + float3(0.6, 0.78, 1.0) * strip2 * 1.1;
  col += float3(0.55, 0.75, 1.0) * (0.25 * pow(d2, 30.0) + 0.9 * pow(d2, 160.0));
  col += float3(1.0, 0.8, 0.6) * (0.15 * pow(d3, 40.0) + 0.5 * pow(d3, 200.0));
  return col;
}

float3 ferrofluidColor(float2 p) {
  float2 o = size * 0.5;
  float3 V = normalize(float3(0.0, 0.6, 1.0));
  float3 vp = normalize(float3((o.x - p.x) * 0.0012, (o.y - p.y) * 0.0012 + 0.6, 1.0));

  float2 q = p;
  float zHit = 0.0;
  float2 dm = p - mag.xy;
  float len = length(dm);
  float2 pn = mag.xy + dm * (max(len - (RB + A + HMAX * 0.6), 0.0) / max(len, 0.001));
  float3 n = float3(0.0, 0.0, 1.0);
  float3 view = vp;
  if (mag.z * fieldRatio(pn) > 1.0) {
    float zPrev = HMAX;
    float2 qPrev = p + float2(0.0, 0.6 * HMAX);
    float hPrev = heightAt(qPrev);
    bool hit = false;
    for (int s = 1; s <= 16; s++) {
      float z = HMAX * (1.0 - float(s) / 16.0);
      float2 qs = p + float2(0.0, 0.6 * z);
      float hh = heightAt(qs);
      if (!hit && z <= hh) {
        float a = zPrev - hPrev;
        float b = zPrev - z - (hPrev - hh);
        float t = clamp(a / max(b, 0.0001), 0.0, 1.0);
        q = mix(qPrev, qs, t);
        zHit = mix(zPrev, z, t);
        hit = true;
      }
      zPrev = z;
      qPrev = qs;
      hPrev = hh;
    }
    if (hit) {
      float e = 0.75;
      float hx = heightAt(q + float2(e, 0.0)) - heightAt(q - float2(e, 0.0));
      float hy = heightAt(q + float2(0.0, e)) - heightAt(q - float2(0.0, e));
      n = normalize(float3(-hx / (2.0 * e), -hy / (2.0 * e), 1.0));
      view = normalize(float3(vp.xy, vp.z));
    } else {
      q = p;
      zHit = 0.0;
    }
  }
  float3 r = reflect(-view, n);
  float cosT = clamp(dot(n, view), 0.0, 1.0);
  float fres = 0.30 + 0.70 * pow(1.0 - cosT, 5.0);
  float3 col = studio(r) * fres + float3(0.004, 0.005, 0.008);
  col *= 0.6 + 0.4 * clamp(zHit / (HMAX * 0.4), 0.0, 1.0);
  float2 vg = (p - o) / size;
  col *= 1.0 - 0.55 * dot(vg, vg);
  col = col / (1.0 + col * 0.5);
  return pow(col, float3(0.92));
}
`;

export const FERRO_W = 320;
export const FERRO_H = 340;
export const FERRO_BACKGROUND = "#05060a";
// Dish width in millimetres (see FERRO_PX_PER_MM in ferroMath.ts).
export const FERRO_DISH_MM = 130;

import React, { useState } from "react";
import { Pressable, Text, View } from "react-native";
import { Ferrofluid } from "./Ferrofluid";

export default function Example({ onFeedback }: { onFeedback?: (event: "touch" | "release") => void }) {
  const [slow, setSlow] = useState(false);
  const chip = (on: boolean) => ({
    paddingVertical: 9, paddingHorizontal: 13, borderRadius: 24, borderWidth: 1,
    backgroundColor: on ? "#315843" : "#eeeade", borderColor: on ? "#315843" : "#c7caba",
  });
  return (
    <View style={{ alignItems: "center", gap: 10, paddingVertical: 14 }}>
      <Ferrofluid slowMotion={slow} onFeedback={onFeedback} />
      <View style={{ flexDirection: "row", gap: 8 }}>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: slow }} onPress={() => setSlow((v) => !v)} style={chip(slow)}>
          <Text style={{ fontSize: 12, color: slow ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Slow motion: {slow ? "on" : "off"}</Text>
        </Pressable>
      </View>
      <Text style={{ fontSize: 12, color: "#63705f", fontFamily: "Geist-Regular" }}>Press and hold, then drag. A magnet under the dish follows your finger.</Text>
    </View>
  );
}
